import { Test, TestingModule } from '@nestjs/testing';
import { AppController } from './app.controller';
import { AppService } from './app.service';
import { AppLogger } from '@/common/logger/app-logger';
import { StreamMonitorService } from '@/services/stream-monitor.service';

describe('AppController', () => {
  let appController: AppController;

  const mockStreamMonitorService = {
    collectMetrics: jest.fn(),
    getHealthStatus: jest.fn(),
  };

  const mockAppService = {
    checkHealth: jest.fn(),
  };

  const mockAppLogger = {
    debug: jest.fn(),
    error: jest.fn(),
    log: jest.fn(),
    warn: jest.fn(),
  };

  beforeEach(async () => {
    const app: TestingModule = await Test.createTestingModule({
      controllers: [AppController],
      providers: [
        { provide: AppService, useValue: mockAppService },
        { provide: StreamMonitorService, useValue: mockStreamMonitorService },
        { provide: AppLogger, useValue: mockAppLogger },
      ],
    }).compile();

    appController = app.get<AppController>(AppController);
  });

  describe('getInfo', () => {
    it('should return service info', () => {
      const result = appController.getInfo();
      expect(result).toEqual({
        message: 'KEDA External Scaler for Redis Streams - Order Domain',
        service: 'mesx-redis-stream-scaler',
      });
    });
  });

  describe('getHealth', () => {
    it('should return health status when redis is healthy', async () => {
      mockAppService.checkHealth.mockResolvedValue({
        connected: true,
        latencyMs: 5,
      });

      const result = await appController.getHealth();

      expect(result).toHaveProperty('status', 'healthy');
      expect(result).toHaveProperty('redis');
      expect((result as Record<string, unknown>).redis).toEqual({
        connected: true,
        latencyMs: 5,
      });
      expect(result).toHaveProperty('timestamp');
    });

    it('should return unhealthy status when redis is not connected', async () => {
      mockAppService.checkHealth.mockResolvedValue({
        connected: false,
      });

      const result = await appController.getHealth();

      expect(result).toHaveProperty('status', 'unhealthy');
      expect((result as Record<string, unknown>).redis).toEqual({
        connected: false,
      });
    });
  });
});

import { JobsLogContext } from '@mesx/common-lib';
import { Controller, Get } from '@nestjs/common';
import { AppService } from './app.service';
import { AppLogger } from '@/common/logger/app-logger';
import { StreamMonitorService } from '@/services/stream-monitor.service';
import { StreamDetail } from '@/types/scaler.types';

@Controller()
export class AppController {
  private readonly context: JobsLogContext = {
    method: '',
    service: AppController.name,
  };

  public constructor(
    private readonly appService: AppService,
    private readonly streamMonitor: StreamMonitorService,
    private readonly logger: AppLogger,
  ) {}

  @Get('/')
  public getInfo(): { message: string; service: string } {
    this.context.method = 'getInfo';
    this.logger.debug('Getting service info', this.context);
    return AppService.getServiceInfo();
  }

  @Get('/probes/health')
  public async getHealth(): Promise<object> {
    const redisHealth = await this.appService.checkHealth();

    return {
      redis: {
        connected: redisHealth.connected,
        latencyMs: redisHealth.latencyMs,
      },
      status: redisHealth.connected ? 'healthy' : 'unhealthy',
      timestamp: new Date().toISOString(),
    };
  }

  @Get('/metrics')
  public async getMetrics(): Promise<object> {
    const metrics = await this.streamMonitor.collectMetrics();

    return {
      activeStreamCount: metrics.activeStreamCount,
      averageMessagesPerStream:
        Math.round(metrics.averageMessagesPerStream * 100) / 100,
      domain: 'order',
      estimatedReplicasNeeded: metrics.estimatedReplicasNeeded,
      heavyStreamCount: metrics.heavyStreamCount,
      maxMessagesInStream: metrics.maxMessagesInStream,
      timestamp: metrics.timestamp.toISOString(),
      totalPendingMessages: metrics.totalPendingMessages,
    };
  }

  @Get('/streams')
  public async getStreams(): Promise<object> {
    const metrics = await this.streamMonitor.collectMetrics();

    const streamList = [...metrics.streamDetails.values()]
      .sort(
        (a: StreamDetail, b: StreamDetail) => b.messageCount - a.messageCount,
      )
      .map((stream: StreamDetail) => ({
        isHeavy: stream.isHeavy,
        messageCount: stream.messageCount,
        streamKey: stream.streamKey,
      }));

    return {
      domain: 'order',
      streams: streamList,
      timestamp: metrics.timestamp.toISOString(),
      totalStreams: streamList.length,
    };
  }
}

