interface CacheEntry {
  value: string | undefined;
  expiresAt: number;
}

@Injectable()
export class AppConfigService {
  private readonly appConfigClient: AppConfigurationClient;

  private readonly cache: Map<string, CacheEntry> = new Map();

  private readonly cacheTTL: number;

  public constructor(
    private readonly appConfigConfigService: AppConfigInitialConfigService,
  ) {
    const credential = new DefaultAzureCredential();
    this.appConfigClient = new AppConfigurationClient(
      this.appConfigConfigService.appConfigEndpoint,
      credential,
    );
    this.cacheTTL = appConfigConfigService.appConfigCachingTtl;
  }

  public get configStoreId(): string {
    return this.appConfigConfigService.appConfigEndpoint;
  }

  public async keyIsDefined(key: string): Promise<boolean> {
    try {
      const result = await this.appConfigClient.getConfigurationSetting({
        key,
      });

      return result !== undefined;
    } catch (error) {
      Logger.error(
        `Error When Reading configuration key '${key}' from '${this.appConfigConfigService.appConfigEndpoint}'`,
      );
      throw error;
    }
  }

  public async getConfigurationValue(key: string): Promise<string | undefined> {
    const currentTimeStamp: number = Date.now();
    const cachedEntry = this.cache.get(key);

    if (cachedEntry && cachedEntry.expiresAt > currentTimeStamp) {
      return cachedEntry.value;
    }
    const value = await this.getConfigValueFromStore(key);

    this.cache.set(key, { expiresAt: currentTimeStamp + this.cacheTTL, value });
    return value;
  }

  private async getConfigValueFromStore(
    key: string,
  ): Promise<string | undefined> {
    try {
      const result = await this.appConfigClient.getConfigurationSetting({
        key,
      });

      return result?.value;
    } catch (error) {
      Logger.error(
        `Error When Reading configuration key '${key}' from '${this.appConfigConfigService.appConfigEndpoint}'`,
        error.stack,
      );
      throw error;
    }
  }

  public async reachable(): Promise<boolean> {
    try {
      this.appConfigClient.listConfigurationSettings();

      return true;
    } catch (error) {
      Logger.error(
        `Error when trying to reach config store '${this.appConfigConfigService.appConfigEndpoint}'`,
        error.stack,
      );
      return false;
    }
  }
}

