  @Get('metrics/pending-messages')
  @Header('Content-Type', 'application/json')
  public async getPendingMessagesMetric(): Promise<{ metricValue: number }> {
    try {
      // Collect current metrics from Redis
      const metrics = await this.streamMonitor.collectMetrics();

      this.logger.debug('Metrics API called', {
        method: 'getPendingMessagesMetric',
        service: MetricsController.name,
      });

      // Return simple JSON for KEDA metrics-api scaler
      return {
        metricValue: metrics.totalPendingMessages,
      };
    } catch (error) {
      this.logger.error(
        'Failed to get pending messages metric',
        {
          method: 'getPendingMessagesMetric',
          service: MetricsController.name,
        },
        error,
      );

      // Return 0 on error to prevent scaling issues
      return {
        metricValue: 0,
      };
    }
  }

  // Active streams count endpoint (optimized)
  @Get('metrics/active-streams')
  @Header('Content-Type', 'application/json')
  public async getActiveStreamsMetric(
    @Req() request: Request,
  ): Promise<{ activeStreamsCount: number }> {
    try {
      const activeStreamsCount =
        await this.streamMonitor.getActiveStreamCount();

      const userAgent = request.headers['user-agent'] || 'unknown';
      const forwarded = request.headers['x-forwarded-for'] || request.ip;
      // Log request details to identify caller
      this.logger.debug(
        `ð Active streams metric: ${activeStreamsCount} | ` +
          `UA: ${userAgent} | ` +
          `IP: ${forwarded} | ` +
          `Host: ${request.headers.host} | ` +
          `Origin: ${request.headers.origin || 'none'}`,
        {
          method: 'getActiveStreamsMetric',
          service: MetricsController.name,
        },
      );

      return { activeStreamsCount };
    } catch (error) {
      this.logger.error(
        'Failed to get active streams metric',
        { method: 'getActiveStreamsMetric', service: MetricsController.name },
        error,
      );
      return { activeStreamsCount: 0 };
    }
  }
}

