import {
  JobsLogContext,
  RedisConnectionService,
  RedisClientInstance,
} from '@mesx/common-lib';
import { Injectable, OnModuleDestroy, OnModuleInit } from '@nestjs/common';
import { ScanOptionsDto } from './dto/scan-options.dto';
import { AppLogger } from '@/common/logger/app-logger';
import { StreamDetail, StreamMetrics } from '@/types/scaler.types';

@Injectable()
export class StreamMonitorService implements OnModuleInit, OnModuleDestroy {
  private static createEmptyMetrics(): StreamMetrics {
    return {
      activeStreamCount: 0,
      averageMessagesPerStream: 0,
      estimatedReplicasNeeded: 0,
      heavyStreamCount: 0,
      maxMessagesInStream: 0,
      streamDetails: new Map(),
      timestamp: new Date(),

      totalPendingMessages: 0,
    };
  }

  private readonly context: JobsLogContext = {
    method: '',
    service: StreamMonitorService.name,
  };

  // â­ HARDCODED for ORDER domain POC
  private readonly streamKeyPattern =
    process.env.STREAM_KEY_PATTERN || 'order_stream:*'; // Pattern to discover order streams

  private readonly heavyStreamThreshold =
    Number(process.env.HEAVY_STREAM_THRESHOLD) || 500; // Threshold for heavy stream;

  private redisClient: RedisClientInstance | undefined;

  private readonly cacheTTLMS = 10_000; // 10 seconds

  // Cache for active stream count
  private cachedActiveStreamCount: number | null = null;

  private lastActiveStreamCountUpdate: Date = new Date(0);

  public constructor(
    private readonly redisConnectionFactory: RedisConnectionService,
    private readonly customLogger: AppLogger,
  ) {
    this.context.method = 'constructor';
    this.customLogger.debug(
      `ð¯ Stream monitor initialized for ORDER domain | ` +
        `pattern=${this.streamKeyPattern}, ` +
        `heavyThreshold=${this.heavyStreamThreshold}`,
      this.context,
    );
  }

  public async onModuleInit(): Promise<void> {
    this.context.method = 'onModuleInit';
    this.redisClient = await this.redisConnectionFactory.getClient();
  }

  public async onModuleDestroy(): Promise<void> {
    this.context.method = 'onModuleDestroy';
    await this.cleanup();
  }

  /**
   * Optimized method to get only active stream count (streams with length > 0)
   * Uses separate cache with shorter TTL for frequent polling
   * @returns Promise<number> - Count of active streams
   */
  public async getActiveStreamCount(): Promise<number> {
    this.context.method = 'getActiveStreamCount';

    // Return cached count if fresh
    const now = new Date();
    const cacheAge = now.getTime() - this.lastActiveStreamCountUpdate.getTime();

    if (this.cachedActiveStreamCount !== null && cacheAge < this.cacheTTLMS) {
      this.customLogger.debug(
        `Returning cached active stream count: ${this.cachedActiveStreamCount}`,
        this.context,
      );
      return this.cachedActiveStreamCount;
    }

    const startTime = Date.now();

    if (!this.redisClient || !this.redisClient.isReady) {
      throw new Error('Redis client is not initialized or not ready');
    }

    const streamKeys = await this.discoverStreams(this.streamKeyPattern);

    if (streamKeys.length === 0) {
      this.customLogger.debug('No order streams found', this.context);
      this.cachedActiveStreamCount = 0;
      this.lastActiveStreamCountUpdate = now;
      return 0;
    }

    let activeStreams = 0;

    // Only count streams with messages > 0
    for (const streamKey of streamKeys) {
      try {
        const messageCount = await this.redisClient.xLen(streamKey);
        if (messageCount > 0) {
          activeStreams += 1;
        }
      } catch (error) {
        this.customLogger.error(
          `Failed to check stream ${streamKey}`,
          this.context,
          error,
        );
      }
    }

    const duration = Date.now() - startTime;
    this.customLogger.debug(
      `ð [ORDER] Active streams: ${activeStreams} out of ${streamKeys.length} total [${duration}ms]`,
      this.context,
    );

    // Cache the result
    this.cachedActiveStreamCount = activeStreams;
    this.lastActiveStreamCountUpdate = now;

    return activeStreams;
  }

  public async collectMetrics(): Promise<StreamMetrics> {
    this.context.method = 'collectMetrics';
    const startTime = Date.now();

    if (!this.redisClient || !this.redisClient.isReady) {
      throw new Error('Redis client is not initialized or not ready');
    }

    const streamKeys = await this.discoverStreams(this.streamKeyPattern);

    if (streamKeys.length === 0) {
      this.customLogger.debug('No order streams found', this.context);
      const emptyMetrics = StreamMonitorService.createEmptyMetrics();
      return emptyMetrics;
    }

    const streamDetails = new Map<string, StreamDetail>();
    let totalMessages = 0;
    let activeStreams = 0;
    let heavyStreams = 0;
    let maxMessages = 0;

    for (const streamKey of streamKeys) {
      try {
        const messageCount = await this.redisClient.xLen(streamKey);
        if (messageCount > 0) {
          activeStreams += 1;
          totalMessages += messageCount;
          maxMessages = Math.max(maxMessages, messageCount);

          const isHeavy = messageCount > this.heavyStreamThreshold;
          if (isHeavy) {
            heavyStreams += 1;
          }

          streamDetails.set(streamKey, {
            isHeavy,
            messageCount,
            streamKey,
          });
        }
      } catch (error) {
        this.customLogger.error(
          `Failed to check stream ${streamKey}`,
          this.context,
          error,
        );
      }
    }

    // Calculate replicas needed:
    // 1. One replica per heavy stream (>threshold messages)
    // 2. For remaining non-heavy streams: group them and create replicas based on target
    let nonHeavyStreamMessages = 0;

    for (const detail of streamDetails.values()) {
      if (!detail.isHeavy) {
        nonHeavyStreamMessages += detail.messageCount;
      }
    }

    // One replica per heavy stream + replicas for grouped non-heavy streams
    const replicasForHeavyStreams = heavyStreams;
    const replicasForNonHeavyStreams = Math.ceil(
      nonHeavyStreamMessages / this.heavyStreamThreshold,
    );
    const estimatedReplicas =
      replicasForHeavyStreams + replicasForNonHeavyStreams;

    const metrics: StreamMetrics = {
      activeStreamCount: activeStreams,
      averageMessagesPerStream:
        activeStreams > 0 ? totalMessages / activeStreams : 0,
      estimatedReplicasNeeded: estimatedReplicas,
      heavyStreamCount: heavyStreams,
      maxMessagesInStream: maxMessages,
      streamDetails,
      timestamp: new Date(),
      totalPendingMessages: totalMessages,
    };

    const duration = Date.now() - startTime;
    this.customLogger.debug(
      `ð [ORDER] Metrics: ${totalMessages} msgs across ${activeStreams} streams ` +
        `(${heavyStreams} heavy, ${activeStreams - heavyStreams} normal) â ` +
        `${estimatedReplicas} replicas (${replicasForHeavyStreams} for heavy + ${replicasForNonHeavyStreams} for grouped) [${duration}ms]`,
      this.context,
    );

    if (streamDetails.size > 0) {
      const topStreams = [...streamDetails.values()]
        .sort((a, b) => b.messageCount - a.messageCount)
        .slice(0, 5);

      this.customLogger.debug(
        `[ORDER] Top streams: ${topStreams
          .map(
            (s) =>
              `${s.streamKey.replace('order-stream:', '')}(${s.messageCount})`,
          )
          .join(', ')}`,
        this.context,
      );
    }

    return metrics;
  }

  private async discoverStreams(pattern: string): Promise<Array<string>> {
    this.context.method = 'discoverStreams';

    if (!this.redisClient || !this.redisClient.isReady) {
      throw new Error('Redis client is not initialized or not ready');
    }

    const discoveredKeys: Array<string> = [];
    let scanCursor = 0;

    do {
      const scanOptions = new ScanOptionsDto(100, pattern);
      const scanResult = await this.redisClient.scan(
        String(scanCursor),
        scanOptions,
      );
      scanCursor = Number(scanResult.cursor);
      discoveredKeys.push(...scanResult.keys);
    } while (scanCursor !== 0);

    this.customLogger.debug(
      `[ORDER] Discovered ${discoveredKeys.length} streams`,
      this.context,
    );

    return discoveredKeys;
  }

  public async getHealthStatus(): Promise<{
    connected: boolean;
    latencyMs?: number;
  }> {
    this.context.method = 'getHealthStatus';

    try {
      if (!this.redisClient || !this.redisClient.isReady) {
        return { connected: false };
      }

      const start = Date.now();
      await this.redisClient.ping();
      const latency = Date.now() - start;

      return { connected: true, latencyMs: latency };
    } catch (error) {
      this.customLogger.error('Health check failed', this.context, error);
      return { connected: false };
    }
  }

  public async cleanup(): Promise<void> {
    this.context.method = 'cleanup';

    if (this.redisClient && this.redisClient.isOpen) {
      await this.redisClient.quit();
      this.customLogger.log('Redis client disconnected', this.context);
    }
  }
}

